-- Photos des promos Victory Müller (patron, 18/11) : petite photo dans le produit (son empreinte) → fichier de l'appli (grande photo)
do $$
declare d text;
begin
  d := 'data:image/webp;base64,';
  update public.shop_products set photo = d where id = md5('HOPVICTORY:muller-hy907')::uuid;
  insert into public.shop_photo_files (h, path) values (md5(d), 'img/victory/muller-gaufrier-hy907.webp') on conflict (h) do update set path = excluded.path;
  d := 'data:image/webp;base64,';
  update public.shop_products set photo = d where id = md5('HOPVICTORY:muller-nd180ma')::uuid;
  insert into public.shop_photo_files (h, path) values (md5(d), 'img/victory/muller-cheminee-nd180ma.webp') on conflict (h) do update set path = excluded.path;
  d := 'data:image/webp;base64,';
  update public.shop_products set photo = d where id = md5('HOPVICTORY:muller-sp3000l')::uuid;
  insert into public.shop_photo_files (h, path) values (md5(d), 'img/victory/muller-parasol-sp3000l.webp') on conflict (h) do update set path = excluded.path;
end $$;
